module tb;
    reg p1a, p1b, p1c, p1d, p1e, p1f;
    reg p2a, p2b, p2c, p2d;
    wire p1y, p2y;

    TopModule dut (
        .p1a(p1a), .p1b(p1b), .p1c(p1c), .p1d(p1d), .p1e(p1e), .p1f(p1f),
        .p2a(p2a), .p2b(p2b), .p2c(p2c), .p2d(p2d),
        .p1y(p1y), .p2y(p2y)
    );

    integer i;
    reg exp_p1y, exp_p2y;

    initial begin
        for (i = 0; i < 1024; i = i + 1) {p1a, p1b, p1c, p1d, p1e, p1f, p2a, p2b, p2c, p2d} = i[9:0];
        #1;
        exp_p1y = (p1a & p1b & p1c) | (p1d & p1e & p1f);
        exp_p2y = (p2a & p2b) | (p2c & p2d);
        if (p1y !== exp_p1y || p2y !== exp_p2y) begin
            $display("SELFTEST FAIL: inputs=%b, got p1y=%b p2y=%b, exp p1y=%b p2y=%b",
                     i[9:0], p1y, p2y, exp_p1y, exp_p2y);
            $finish;
        end
        #1;
    end

    initial begin
        // Wait and loop properly
        for (i = 0; i < 1024; i = i + 1) begin
            {p1a, p1b, p1c, p1d, p1e, p1f, p2a, p2b, p2c, p2d} = i[9:0];
            #1;
            exp_p1y = (p1a & p1b & p1c) | (p1d & p1e & p1f);
            exp_p2y = (p2a & p2b) | (p2c & p2d);
            if (p1y !== exp_p1y || p2y !== exp_p2y) begin
                $display("SELFTEST FAIL: inputs=%b, got p1y=%b p2y=%b, exp p1y=%b p2y=%b",
                         i[9:0], p1y, p2y, exp_p1y, exp_p2y);
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule
